"""Argument parsing and lazy server/client dispatch."""

import argparse
import os

from .domain import APIError, parse_timestamp


def _nonempty(value):
    if not value:
        raise argparse.ArgumentTypeError("must not be empty")
    return value


def _port(value):
    number = int(value)
    if not 0 <= number <= 65535:
        raise argparse.ArgumentTypeError("must be between 0 and 65535")
    return number


def _rate_limit(value):
    number = int(value)
    if number < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return number


def _timestamp(value):
    try:
        return parse_timestamp(value)
    except APIError as error:
        raise argparse.ArgumentTypeError(error.message) from None


def _client_options(parser):
    # Suppressed defaults preserve options supplied before the token create leaf.
    parser.add_argument("--server", default=argparse.SUPPRESS)
    parser.add_argument("--token", default=argparse.SUPPRESS)


def _parser():
    parser = argparse.ArgumentParser(prog="linkvault")
    commands = parser.add_subparsers(dest="command", required=True)

    serve = commands.add_parser("serve")
    serve.add_argument("--db", required=True)
    serve.add_argument("--admin-key", required=True, type=_nonempty)
    serve.add_argument("--port", type=_port, default=8000)
    serve.add_argument("--rate-limit", type=_rate_limit, default=60)
    serve.add_argument("--fake-clock", type=_timestamp)

    token = commands.add_parser("token")
    _client_options(token)
    token_commands = token.add_subparsers(dest="token_command", required=True)
    create = token_commands.add_parser("create")
    _client_options(create)
    create.add_argument("--admin-key", required=True, type=_nonempty)

    shorten = commands.add_parser("shorten")
    _client_options(shorten)
    shorten.add_argument("url")
    shorten.add_argument("--slug")
    shorten.add_argument("--expires-in", type=int)

    listing = commands.add_parser("list")
    _client_options(listing)
    for name in ("stats", "delete"):
        command = commands.add_parser(name)
        _client_options(command)
        command.add_argument("slug")
    return parser


def main(argv=None):
    parser = _parser()
    try:
        args = parser.parse_args(argv)
        if args.command != "serve":
            args.server = getattr(args, "server", os.environ.get("LINKVAULT_SERVER"))
            args.token = getattr(args, "token", os.environ.get("LINKVAULT_TOKEN"))
            if not args.server:
                parser.error("--server or LINKVAULT_SERVER is required")
            if args.command != "token" and not args.token:
                parser.error("--token or LINKVAULT_TOKEN is required")
    except SystemExit as error:
        return error.code

    if args.command == "serve":
        from . import server

        return server.run(args)

    from . import client

    return client.run(args)

"""Small urllib client with explicit HTTP status and output handling."""

from http.client import HTTPException
import json
import sys
from urllib.error import HTTPError, URLError
from urllib.parse import quote
from urllib.request import HTTPRedirectHandler, Request, build_opener

from .domain import json_bytes


class _NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, request, response, code, message, headers, new_url):
        return None


def run(args):
    method, path, body = "GET", "/v1/links", None
    headers = {}
    if args.command == "token":
        method, path = "POST", "/v1/tokens"
        headers["X-Admin-Key"] = args.admin_key
    else:
        headers["Authorization"] = "Bearer " + args.token
        if args.command == "shorten":
            method = "POST"
            value = {"url": args.url}
            if args.slug is not None:
                value["slug"] = args.slug
            if args.expires_in is not None:
                value["expires_in"] = args.expires_in
            body = json_bytes(value)
            headers["Content-Type"] = "application/json"
        elif args.command in ("stats", "delete"):
            path += "/" + quote(args.slug, safe="")
            if args.command == "delete":
                method = "DELETE"

    try:
        request = Request(args.server.rstrip("/") + path, data=body,
                          headers=headers, method=method)
        try:
            response = build_opener(_NoRedirect()).open(request, timeout=5)
        except HTTPError as error:
            # HTTPError is also a response, and must precede URLError handling.
            response = error
        with response:
            status = response.code
            raw = response.read()
    except (URLError, OSError, HTTPException, ValueError) as error:
        print("Connection failure: " + str(error), file=sys.stderr)
        return 3

    success = 200 <= status < 300
    if status == 204:
        return 0
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeError, ValueError):
        if success:
            print("Invalid JSON response", file=sys.stderr)
            return 3
        # Redirects and non-API peers may have empty or non-JSON error bodies.
        value = {"error": {"code": "http_error", "message": "HTTP " + str(status)}}
    output = sys.stdout if success else sys.stderr
    print(json_bytes(value).decode("utf-8"), file=output)
    return 0 if success else 1

"""Exact loopback HTTP API and signal-driven, drained server lifecycle."""

from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import signal
import socket
import sys
import threading

from .domain import (
    APIError, Clock, RateLimiter, decode_json, format_timestamp, json_bytes,
    valid_slug, validate_clock,
)
from .storage import Storage


class Server(ThreadingHTTPServer):
    # Join every handler before the caller closes the shared database.
    daemon_threads = False
    block_on_close = True

    def __init__(self, storage: Storage, admin_key: str, port: int,
                 rate_limit: int = 60, fake_clock: int | None = None):
        self.storage = storage
        self.admin_key = admin_key
        self.clock = Clock(fake_clock)
        self.limiter = RateLimiter(rate_limit)
        self._active = set()
        self._active_lock = threading.Lock()
        super().__init__(("127.0.0.1", port), Handler)
        self.base_url = f"http://127.0.0.1:{self.server_port}"

    def process_request(self, request, client_address):
        with self._active_lock:
            self._active.add(request)
        try:
            super().process_request(request, client_address)
        except BaseException:
            with self._active_lock:
                self._active.discard(request)
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            with self._active_lock:
                self._active.discard(request)

    def server_close(self):
        # Call after shutdown(): no more sockets can enter the active set.
        with self._active_lock:
            for request in self._active:
                try:
                    request.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
        super().server_close()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def __getattr__(self, name):
        # BaseHTTPRequestHandler otherwise sends HTML 501 for extension methods.
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    def log_message(self, format, *args):
        # No per-request logs, and in particular no stdout output.
        pass

    def _route(self):
        # self.path is normalized by the stdlib for leading '//'; do not use it.
        path = self.requestline.split()[1].split("?", 1)[0]
        method = self.command
        if (method, path) == ("GET", "/healthz"):
            return "health", None
        if (method, path) == ("POST", "/v1/tokens"):
            return "token", None
        if path == "/v1/links" and method in ("POST", "GET"):
            return ("create" if method == "POST" else "list"), None
        if (method, path) == ("POST", "/v1/admin/clock") and self.server.clock.is_fake:
            return "clock", None
        if path.startswith("/v1/links/") and method in ("GET", "DELETE"):
            slug = path[len("/v1/links/"):]
            if valid_slug(slug):
                return ("get" if method == "GET" else "delete"), slug
        if method == "GET" and path.startswith("/") and valid_slug(path[1:]):
            return "resolve", path[1:]
        raise APIError(404, "not_found", "Route not found")

    def _authenticate(self, route):
        if route in ("token", "clock"):
            if self.headers.get_all("X-Admin-Key") != [self.server.admin_key]:
                raise APIError(401, "unauthorized", "Invalid admin key")
        elif route in ("create", "list", "get", "delete"):
            values = self.headers.get_all("Authorization", [])
            if len(values) != 1 or not values[0].startswith("Bearer "):
                raise APIError(401, "unauthorized", "Expected Bearer token")
            return self.server.storage.authenticate(values[0][len("Bearer "):])
        return None

    def _body_length(self):
        values = self.headers.get_all("Content-Length", [])
        if not values:
            length = 0
        elif len(values) == 1 and values[0].isascii() and values[0].isdigit():
            length = int(values[0])
        else:
            raise APIError(400, "invalid_request", "Invalid Content-Length")
        if length > 8192:
            raise APIError(413, "payload_too_large", "Body exceeds 8192 bytes",
                           {"Connection": "close"})
        if self.headers.get("Transfer-Encoding") is not None:
            raise APIError(400, "invalid_request", "Unsupported body framing")
        return length

    def _write(self, status, body=None, headers=None):
        payload = b"" if body is None else json_bytes(body)
        self.send_response(status)
        if body is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        for key, value in (headers or {}).items():
            if key == "Location":
                # Preserve Latin-1 wire compatibility where possible. For other
                # Unicode URLs emit the original value's UTF-8 octets, without
                # percent-encoding, IDNA, or any URL normalization.
                try:
                    value.encode("latin-1")
                except UnicodeEncodeError:
                    value = value.encode("utf-8").decode("latin-1")
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(payload)

    def _dispatch(self):
        # HTTP/1.0 closes even when an ignored body is left unread.
        self.close_connection = True
        try:
            route, slug = self._route()
            now = self.server.clock.now()
            owner = self._authenticate(route)
            if owner is not None:
                self.server.limiter.check(owner, now)
            length = self._body_length()
            body = None
            if route in ("create", "clock"):
                raw = self.rfile.read(length)
                if len(raw) != length:
                    raise APIError(400, "invalid_json", "Incomplete JSON body")
                body = decode_json(raw)
            storage = self.server.storage
            base_url = self.server.base_url
            if route == "health":
                self._write(200, {"status": "ok"})
            elif route == "token":
                self._write(201, storage.issue_token(now))
            elif route == "create":
                self._write(201, storage.create_link(owner, body, now, base_url))
            elif route == "list":
                self._write(200, storage.list_links(owner, base_url))
            elif route == "get":
                self._write(200, storage.get_link(owner, slug, base_url))
            elif route == "delete":
                storage.delete_link(owner, slug)
